9	/// Host-side CSR for the split-KV decode kernel: padded request/chunk indices,
10	/// the per-slot validity mask, and the per-request chunk offsets.
11	pub struct SplitKvCsr {
12	    pub request_indices: Vec<i32>,
13	    pub kv_tile_indices: Vec<i32>,
14	    pub block_valid_mask: Vec<u8>,
15	    pub o_indptr: Vec<i32>,
16	}
17	
18	/// Build the split-KV CSR for `kv_lens` at a fixed `chunk_size`, padded to
19	/// `padded_bs * cap` slots. Errors if a request needs more than `cap` chunks.
20	pub fn build_split_kv_csr(
21	    chunk_size: usize,
22	    cap: usize,
23	    kv_lens: &[usize],
24	    padded_bs: usize,
25	) -> Result<SplitKvCsr> {
26	    anyhow::ensure!(chunk_size > 0, "split-KV chunk_size must be > 0");
27	    anyhow::ensure!(cap > 0, "split-KV cap must be > 0");
28	    anyhow::ensure!(
29	        kv_lens.len() <= padded_bs,
30	        "kv_lens length {} exceeds padded batch {padded_bs}",
31	        kv_lens.len()
32	    );
33	    let padded_slots = padded_bs * cap;
34	    let mut request_indices = Vec::with_capacity(padded_slots);
35	    let mut kv_tile_indices = Vec::with_capacity(padded_slots);
36	    let mut block_valid_mask = Vec::with_capacity(padded_slots);
37	    let mut o_indptr = Vec::with_capacity(padded_bs + 1);
38	    o_indptr.push(0);
39	
40	    for (request_idx, &kv_len) in kv_lens.iter().enumerate() {
41	        let chunks = kv_len.div_ceil(chunk_size).max(1);
42	        anyhow::ensure!(
43	            chunks <= cap,
44	            "split-KV chunk count {chunks} exceeds bound {cap} \
45	             (kv_len={kv_len}, chunk_size={chunk_size}); context limit misconfigured"
46	        );
47	        for chunk_idx in 0..chunks {
48	            request_indices.push(request_idx as i32);
49	            kv_tile_indices.push(chunk_idx as i32);
50	            block_valid_mask.push(1);
51	        }
52	        o_indptr.push(request_indices.len() as i32);
53	    }
54	    for _ in kv_lens.len()..padded_bs {
55	        o_indptr.push(request_indices.len() as i32);
56	    }
57	    while request_indices.len() < padded_slots {
58	        request_indices.push(0);
59	        kv_tile_indices.push(0);
60	        block_valid_mask.push(0);
61	    }
62	
63	    Ok(SplitKvCsr {
64	        request_indices,
65	        kv_tile_indices,
66	        block_valid_mask,
67	        o_indptr,
68	    })
69	}
