132	        last_page_lens: &[usize],
133	        start_positions: &[usize],
134	        seq_lens: &[usize],
135	        num_q_heads: usize,
136	        num_kv_heads: usize,
137	        head_dim: usize,
138	        cta_tile_q_override: i32,
139	    ) -> Result<Self> {
140	        Ok(Self {
141	            inner: pegainfer_kernels::ops::PrefillPagedPlan::new_batch_with_cta_tile_q(
142	                ctx,
143	                page_indices,
144	                last_page_lens,
145	                start_positions,
146	                seq_lens,
147	                num_q_heads,
148	                num_kv_heads,
149	                head_dim,
150	                cta_tile_q_override,
151	            )?,
152	        })
153	    }
154	
155	    /// Pre-allocate a worst-case-sized plan to be refilled in place by
156	    /// [`Self::update_batch_with_cta_tile_q`] (graph-stable buffer reuse).
157	    pub fn new_preallocated(
158	        ctx: &DeviceContext,
159	        max_total_tokens: usize,
160	        max_total_pages: usize,
161	        max_batch: usize,
162	        max_tiles: usize,
163	    ) -> Result<Self> {
164	        Ok(Self {
