210	/// empty unless `result` is the -1 sentinel set by the C++ guard. Public for
211	/// crates that call guarded FFI entries directly instead of through a wrapper.
212	pub fn ffi_exception_message(result: i32) -> String {
213	    if result != -1 {
214	        return String::new();
215	    }
216	    let ptr = unsafe { crate::ffi::pegainfer_kernels_last_error() };
217	    if ptr.is_null() {
218	        return String::new();
