use std::sync::Arc;

use anyhow::Result;
use anyhow::bail;
use cudarc::driver::CudaSlice;
use half::bf16;
pub use pegainfer_kernels::paged_kv::KvStorage;

use crate::page_pool::OwnedPagePermit;
use crate::page_pool::PageId;
use crate::page_pool::PagePool;
use crate::tensor::DeviceContext;

/// Page-first geometry: dimensions and derived strides for one page.
///
/// Pure value type — no GPU, no allocation. Shared by `KvPool`, `KvState`, `KvDesc`.
#[derive(Clone, Copy, Debug)]
pub struct KvLayout {
    pub page_size: usize,
    pub num_layers: usize,
    pub num_kv_heads: usize,
    pub head_dim: usize,
    /// Elements in one K (or V) block: page_size × num_kv_heads × head_dim.
    pub kv_block_len: usize,
    /// Elements between layers within a page: 2 × kv_block_len (K then V).
    pub layer_stride: usize,
    /// Elements per page (all layers): num_layers × layer_stride.
    pub page_stride: usize,
    pub storage: KvStorage,
}

impl KvLayout {
    pub fn new(
        num_layers: usize,
        num_kv_heads: usize,
        head_dim: usize,
        page_size: usize,
    ) -> anyhow::Result<Self> {
        Self::with_storage(
            num_layers,
            num_kv_heads,
            head_dim,
            page_size,
            KvStorage::Bf16,
        )
    }

    pub fn with_storage(
        num_layers: usize,
        num_kv_heads: usize,
        head_dim: usize,
        page_size: usize,
        storage: KvStorage,
    ) -> anyhow::Result<Self> {
        let strides = || -> Option<(usize, usize, usize)> {
            let kv_block_len = page_size.checked_mul(num_kv_heads)?.checked_mul(head_dim)?;
            let layer_stride = kv_block_len.checked_mul(2)?;
            let page_stride = num_layers.checked_mul(layer_stride)?;
            Some((kv_block_len, layer_stride, page_stride))
        };
        let (kv_block_len, layer_stride, page_stride) = strides().ok_or_else(|| {
            anyhow::anyhow!(
                "kv layout strides overflow usize: {num_layers} layers x {num_kv_heads} heads x \
                 {head_dim} dim x {page_size} page"
            )
        })?;
        Ok(Self {
            page_size,
            num_layers,
            num_kv_heads,
            head_dim,
            kv_block_len,
            layer_stride,
            page_stride,
            storage,
        })
    }

    pub fn kernel_layout(&self) -> pegainfer_kernels::paged_kv::PagedKvLayout {
        pegainfer_kernels::paged_kv::PagedKvLayout {
            page_size: self.page_size,
            num_layers: self.num_layers,
            num_kv_heads: self.num_kv_heads,
            head_dim: self.head_dim,
            kv_block_len: self.kv_block_len,
            layer_stride: self.layer_stride,
            page_stride: self.page_stride,
            storage: self.storage,
        }
    }
}

struct KvPoolInner {
    pool: PagePool,
    buffer: CudaSlice<bf16>,
    layout: KvLayout,
    /// Reserved page for bucket CUDA Graph padding. FlashInfer metadata for
    /// padding slots points here with seq_len=1. KV append writes harmless
    /// garbage; attention output is discarded.
    padding_permit: OwnedPagePermit,

}

/// Batched paged attention decode: append K/V + FlashInfer BatchDecode for batch_size >= 1.
///
/// Q: HiddenStates [q_dim, batch_size], output: HiddenStates [q_dim, batch_size].
/// Metadata arrays are concatenated across requests (CSR format).
#[allow(clippy::too_many_arguments)]
pub fn paged_attention_batch_decode_into(
    ctx: &DeviceContext,
    q: &HiddenStates,
    k: &HiddenStates,
    v: &HiddenStates,
    kv_buffer: &CudaSlice<bf16>,
    layout: &PagedKvLayout,
    layer: usize,
    page_indices_d: &CudaSlice<i32>,
    page_indptr_d: &CudaSlice<i32>,
    last_page_len_d: &CudaSlice<i32>,
    positions_d: &CudaSlice<i32>,
    request_indices_d: &CudaSlice<i32>,
    kv_tile_indices_d: &CudaSlice<i32>,
    kv_chunk_size_d: &CudaSlice<i32>,
    output: &mut HiddenStates,
    num_qo_heads: usize,
    batch_size: usize,
) -> Result<()> {
    let num_kv_heads = layout.num_kv_heads;
    let head_dim = layout.head_dim;
    let page_size = layout.page_size;

    let PagedGeometry {
        k_offset_elems: k_offset,
        v_offset_elems: v_offset,
        stride_page,
        ..
    } = checked_paged_geometry(
        "batch decode",
        layout,
        kv_buffer.len(),
        layer,
        head_dim,
        num_kv_heads,
        false,
    )?;

    let (buf_ptr, _gbuf) = kv_buffer.device_ptr(&ctx.stream);
    let (q_ptr, _gq) = q.data.device_ptr(&ctx.stream);
    let (k_ptr, _gk) = k.data.device_ptr(&ctx.stream);
    let (v_ptr, _gv) = v.data.device_ptr(&ctx.stream);
    let (out_ptr, _go) = output.data.device_ptr_mut(&ctx.stream);
    let (pi_ptr, _gpi) = page_indices_d.device_ptr(&ctx.stream);
    let (pip_ptr, _gpip) = page_indptr_d.device_ptr(&ctx.stream);
    let (lpl_ptr, _glpl) = last_page_len_d.device_ptr(&ctx.stream);
    let (pos_ptr, _gpos) = positions_d.device_ptr(&ctx.stream);
    let (ri_ptr, _gri) = request_indices_d.device_ptr(&ctx.stream);
    let (kti_ptr, _gkti) = kv_tile_indices_d.device_ptr(&ctx.stream);
    let (kcs_ptr, _gkcs) = kv_chunk_size_d.device_ptr(&ctx.stream);

    let stream = crate::tensor::active_cu_stream(ctx);

    // Step 1: Append K/V to paged cache (batched) using the same generic
    // scatter path as prefill, with explicit request indices and positions.
    let src_stride_n = (num_kv_heads * head_dim) as i64;
    let src_stride_h = head_dim as i64;
    let result = unsafe {
        ffi::paged_kv_scatter_cuda(
            buf_ptr as *const ffi::Half,
            k_offset,
            v_offset,
            pi_ptr as *const i32,
            pip_ptr as *const i32,
            lpl_ptr as *const i32,
            k_ptr as *const ffi::Half,
            v_ptr as *const ffi::Half,
            ri_ptr as *const i32,
            pos_ptr as *const i32,
            batch_size as i32,
            num_kv_heads as i32,
            head_dim as i32,
            page_size as i32,
            stride_page,
            src_stride_n,
            src_stride_h,
            stream,
        )
    };
    if result != 0 {
        anyhow::bail!(
            "paged_kv_scatter_cuda (batch decode) failed with error {result}{}",
            crate::ops::ffi_exception_message(result)
        );
    }

    // Step 2: Paged attention decode (batched)
    let sm_scale = 1.0f32 / (head_dim as f32).sqrt();
    let result = unsafe {
        ffi::paged_attention_decode_cuda(
            q_ptr as *const ffi::Half,
            out_ptr as *mut ffi::Half,
            buf_ptr as *const ffi::Half,
            k_offset,
            v_offset,
            pi_ptr as *const i32,
            pip_ptr as *const i32,
            lpl_ptr as *const i32,
            ri_ptr as *const i32,
            kti_ptr as *const i32,
            kcs_ptr as *const i32,
            num_qo_heads as i32,
            num_kv_heads as i32,
            head_dim as i32,
            page_size as i32,
            batch_size as i32,
            stride_page,
            sm_scale,
            stream,
        )
    };
    if result != 0 {
        anyhow::bail!(
            "paged_attention_decode_cuda (batch) failed with error {result}{}",
            crate::ops::ffi_exception_message(result)
        );
    }

    Ok(())
}

/// Batched paged attention decode using FlashInfer partition-KV/split-K.
///

