#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum KvStorage {
    Bf16,
    E4m3,
}

impl KvStorage {
    pub const fn elem_bytes(self) -> usize {
        match self {
            Self::Bf16 => 2,
            Self::E4m3 => 1,
        }
    }
}

/// Page-first geometry used by paged-KV kernels.
///
/// This is kernel-facing shape metadata only. Pool allocation, page ownership,
/// and request state live in the root runtime crate.
#[derive(Clone, Copy, Debug)]
pub struct PagedKvLayout {
    pub page_size: usize,
    pub num_layers: usize,
    pub num_kv_heads: usize,
    pub head_dim: usize,
    /// Elements in one K (or V) block: page_size x num_kv_heads x head_dim.
    pub kv_block_len: usize,
    /// Elements between layers within a page: 2 x kv_block_len (K then V).
    pub layer_stride: usize,
    /// Elements per page (all layers): num_layers x layer_stride.
    pub page_stride: usize,
    pub storage: KvStorage,
}

impl PagedKvLayout {
    pub fn new(num_layers: usize, num_kv_heads: usize, head_dim: usize, page_size: usize) -> Self {
        Self::with_storage(
            num_layers,
            num_kv_heads,
            head_dim,
            page_size,
            KvStorage::Bf16,
        )
    }

    pub fn with_storage(
        num_layers: usize,
        num_kv_heads: usize,
        head_dim: usize,
        page_size: usize,
        storage: KvStorage,
    ) -> Self {
        let kv_block_len = page_size * num_kv_heads * head_dim;
        let layer_stride = 2 * kv_block_len;
        let page_stride = num_layers * layer_stride;
        Self {
            page_size,
            num_layers,
            num_kv_heads,
            head_dim,
            kv_block_len,
            layer_stride,
            page_stride,
            storage,
        }
    }
}

/// Allocate a worst-case-sized plan once, to be refilled in place by
/// [`Self::update_batch_with_cta_tile_q`]. Buffer pointers stay fixed across
/// updates so a CUDA Graph captured against them remains valid on replay.
/// Geometry starts unset; update before forward.
pub fn new_preallocated(
    ctx: &DeviceContext,
    max_total_tokens: usize,
    max_total_pages: usize,
    max_batch: usize,
    max_tiles: usize,
) -> Result<Self> {
    Ok(Self {
        page_indices_d: ctx.stream.alloc_zeros(max_total_pages)?,
        page_indptr_d: ctx.stream.alloc_zeros(max_batch + 1)?,
        last_page_len_d: ctx.stream.alloc_zeros(max_batch)?,
        batch_indices_d: ctx.stream.alloc_zeros(max_total_tokens)?,
        positions_d: ctx.stream.alloc_zeros(max_total_tokens)?,
        q_indptr_d: ctx.stream.alloc_zeros(max_batch + 1)?,
        request_indices_d: ctx.stream.alloc_zeros(max_tiles)?,
        qo_tile_indices_d: ctx.stream.alloc_zeros(max_tiles)?,
        kv_tile_indices_d: ctx.stream.alloc_zeros(max_tiles)?,
        kv_chunk_size_d: ctx.stream.alloc_zeros(max_batch)?,
        total_num_rows_d: ctx.stream.alloc_zeros(1)?,
        num_tiles: 0,
        batch_size: 0,
        total_tokens: 0,
        cta_tile_q: 0,
        head_dim: 0,
        num_qo_heads: 0,
        num_kv_heads: 0,
        max_page_index: -1,
        max_last_page_len: 0,
    })
}

